module logic;
use model {Hit,Search};
use util {reverse};
fn run(text:Text,needle:Text,start:I64)->Search<Hit> {
 let text_len=Text::length(text);
 let needle_len=Text::length(needle);
 let match_bytes=Bytes::length(Text::bytes(needle));
 if start < 0 || start > text_len {
  Invalid(start)
 } else {
  if needle_len == 0 {
   Found(Hit {index:start,prefix:Text::slice(text,0,start),suffix:Text::slice(text,start,text_len-start),match_bytes:match_bytes})
  } else {
   fold(i in text_len,state:Search<Hit>=Missing) {
    match state {
     Found(hit)=>Found(hit),
     Invalid(bad)=>Invalid(bad),
     Missing=>{
      if i >= start && i <= text_len - needle_len {
       let candidate=Text::slice(text,i,needle_len);
       if candidate == needle {
        Found(Hit {index:i,prefix:Text::slice(text,0,i),suffix:Text::slice(text,i+needle_len,text_len-(i+needle_len)),match_bytes:match_bytes})
       } else {Missing}
      } else {Missing}
     }
    }
   }
  }
 }
}

